mapper.select:
SELECT q.quote_id AS quoteId, q.procurement_id AS procurementId, q.vendor_id AS vendorId, p.selected_vendor_id AS selectedVendorId, v.vendor_name AS vendorName, i.item_code AS itemCode, i.item_name AS itemName, i.spec AS spec, i.unit AS unit, p.request_qty AS requestQty, p.required_date AS requiredDate, p.quote_deadline AS quoteDeadline, q.status AS status, q.unit_price AS unitPrice, q.delivery_date AS deliveryDate, q.terms AS terms, q.submitted_at AS submittedAt FROM vendor_quote q JOIN procurement p ON p.procurement_id = q.procurement_id JOIN item i ON i.item_id = p.item_id JOIN vendor v ON v.vendor_id = q.vendor_id
q.vendor_id = #{vendorId} AND q.status = #{status}
ORDER BY CASE WHEN q.status = 'REQUESTED' THEN 0 ELSE 1 END, p.quote_deadline, q.quote_id DESC

mapper.update:
UPDATE procurement
SET status = 'IN_PROGRESS'
WHERE procurement_id = #{procurementId}
  AND selected_vendor_id = #{vendorId}
  AND status = 'ORDERED'

UPDATE procurement
SET status = 'SHIPPED', shipped_at = #{shipmentDate}, updated_at = NOW()
WHERE procurement_id = #{procurementId}
  AND selected_vendor_id = #{vendorId}
  AND status = 'IN_PROGRESS'

UPDATE procurement
SET status = 'SHIPPED', shipped_at = NOW()
WHERE procurement_id = #{procurementId}
  AND selected_vendor_id = #{vendorId}
  AND status = 'RESUPPLYING'

UPDATE procurement
SET status = 'STATEMENT_ISSUED', updated_at = NOW()
WHERE procurement_id = #{procurementId}
  AND selected_vendor_id = #{vendorId}
  AND status = 'RECEIVED'
  AND COALESCE(received_qty, 0) > 0
